def get_running_at_time(time_limit):
    running = {}  # machine -> list of (task, cpu, mem, finish_time)
    for node in doc["nodes"]:
        if node["title"] == "Cell window 10: Task log":
            rows = node["table"]["rows"]
            for row in rows:
                t = int(row[0])
                task = row[1]
                cpu = int(row[4])
                mem = int(row[5])
                run_time = int(row[6])
                event = row[7]
                machine = row[8]

                if t > time_limit:
                    break

                if event == "start":
                    if machine not in running:
                        running[machine] = []
                    running[machine].append((task, cpu, mem, t + run_time))
                elif event in ["finish", "evict", "fail"]:
                    if machine in running:
                        # Remove this task
                        running[machine] = [(tsk, c, m, ft) for tsk, c, m, ft in running[machine] if tsk != task]

    # Filter to only tasks that are still running at time_limit
    result = {}
    for machine, tasks in running.items():
        still_running = [(tsk, c, m, ft) for tsk, c, m, ft in tasks if ft > time_limit]
        if still_running:
            result[machine] = still_running
    return result

